  loadGradeRows=function(){const id=$("gradeStudent").value;if(!id){toast("Choose a student first.");return;}const semester=$("gradeTerm").value,lockKey=`${$("gradeYear").value}|${semester}`,locked=!!state.gradeLocks[lockKey],key=`${id}|${$("gradeYear").value}|${semester}`,record=state.grades[key]||{},marks=semester==="Semester 1"?["p1","p2","p3","exam"]:["p4","p5","p6","exam"];
    $("gradesTable").innerHTML=state.subjects.map(subject=>{const m=record[subject]||{};return `<tr><td><strong>${esc(subject)}</strong></td>${marks.slice(0,3).map((k,i)=>`<td><input type="number" min="0" max="100" step="0.1" data-subject="${esc(subject)}" data-mark="${k}" value="${esc(m[k]??"")}" ${locked?"disabled":""} aria-label="${esc(subject)} ${k}"></td>`).join("")}<td class="semi-average">—</td><td><input type="number" min="0" max="100" step="0.1" data-subject="${esc(subject)}" data-mark="exam" value="${esc(m.exam??"")}" ${locked?"disabled":""} aria-label="${esc(subject)} exam"></td><td>—</td><td class="row-total">—</td></tr>`;}).join("");$("gradesEmpty").hidden=state.subjects.length>0;$("gradeMessage").textContent=locked?`${semester} grade entry is LOCKED by the administrator.`:`${semester}: enter three period marks and an exam mark (0–100). Semester average = sum of four marks ÷ 4.`;updateMarkTotals();};
  updateMarkTotals=function(){const semester=$("gradeTerm")?.value||"Semester 1";document.querySelectorAll("#gradesTable tr").forEach(row=>{const inputs=[...row.querySelectorAll("input")],vals=inputs.map(i=>i.value===""?null:Number(i.value));const all=vals.filter(v=>v!==null);const avg=all.length===4?all.reduce((a,b)=>a+b,0)/4:null;const sem=row.querySelector(".semi-average"),tot=row.querySelector(".row-total");if(sem){sem.textContent=avg===null?(all.length?"Incomplete":"—"):avg.toFixed(1);sem.classList.toggle("grade-red",avg!==null&&avg<75);}if(tot){tot.textContent=avg===null?(all.length?"Incomplete":"—"):avg.toFixed(1);tot.classList.toggle("grade-red",avg!==null&&avg<75);}row.querySelectorAll("input").forEach(i=>{const v=i.value===""?null:Number(i.value);i.classList.toggle("grade-red",v!==null&&v<75);});});const body=$("gradesTable");if(body){body.querySelector(".period-totals")?.remove();const rows=[...body.querySelectorAll("tr")].filter(r=>r.querySelector("input[data-mark]"));const cellAverages=[0,1,2,3].map((col)=>{const values=rows.map(r=>{const input=r.querySelectorAll("input")[col];return input&&input.value!==""?Number(input.value):null;}).filter(v=>v!==null);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null;});const avgCells=[0,1,2].map(i=>cellAverages[i]===null?"—":`<span class="${cellAverages[i]<75?"grade-red":""}">${cellAverages[i].toFixed(1)}</span>`);const completeAverages=rows.map(r=>r.querySelector(".semi-average")?.textContent).filter(v=>v&&v!=="—"&&v!=="Incomplete").map(Number);const overall=completeAverages.length?completeAverages.reduce((a,b)=>a+b,0)/completeAverages.length:null;const tr=document.createElement("tr");tr.className="period-totals";tr.innerHTML=`<td><strong>CLASS AVERAGE</strong></td><td>${avgCells[0]}</td><td>${avgCells[1]}</td><td>${avgCells[2]}</td><td>${overall===null?"—":`<span class="${overall<75?"grade-red":""}">${overall.toFixed(1)}</span>`}</td><td>${cellAverages[3]===null?"—":`<span class="${cellAverages[3]<75?"grade-red":""}">${cellAverages[3].toFixed(1)}</span>`}</td><td>—</td><td>${overall===null?"—":`<span class="${overall<75?"grade-red":""}">${overall.toFixed(1)}</span>`}</td>`;body.appendChild(tr);}};
  saveGrades=function(){const id=$("gradeStudent").value;if(!id){toast("Choose a student first.");return;}const semester=$("gradeTerm").value,key=`${id}|${$("gradeYear").value}|${semester}`,lockKey=`${$("gradeYear").value}|${semester}`;if(state.gradeLocks[lockKey]){toast("Grade entry is locked by the administrator.");return;}const record={};document.querySelectorAll("#gradesTable tr").forEach(row=>{const inputs=[...row.querySelectorAll("input")],subject=inputs[0]?.dataset.subject;if(!subject)return;record[subject]={};inputs.forEach(i=>{const v=i.value.trim();record[subject][i.dataset.mark]=v===""?null:Number(v);});});state.grades[key]=record;persist();toast(`${semester} marks saved on this device.`);};
  makeReport=function(){const id=$("gradeStudent").value;if(!id){toast("Choose a student first.");return;}const s=state.students.find(x=>x.id===id);if(!s)return;const year=$("gradeYear").value;const a=state.grades[`${id}|${year}|Semester 1`]||{},b=state.grades[`${id}|${year}|Semester 2`]||{};const calc=m=>{const vals=[m.p1,m.p2,m.p3,m.exam].filter(v=>v!==null&&v!==undefined&&v!=="").map(Number);return vals.length===4?vals.reduce((x,y)=>x+y,0)/4:null;};const subjects=state.subjects.map(subject=>{const m1=a[subject]||{},m2=b[subject]||{},avg1=calc(m1),avg2=calc(m2),yearAvg=avg1!==null&&avg2!==null?(avg1+avg2)/2:null;return {subject,m1,m2,avg1,avg2,yearAvg};});const available=subjects.filter(x=>x.yearAvg!==null).map(x=>x.yearAvg),yearAvg=available.length?available.reduce((x,y)=>x+y,0)/available.length:null;const mark=v=>v===null||v===undefined?"—":`<span class="${Number(v)<75?"grade-red":""}">${Number(v).toFixed(1)}</span>`;$("reportContent").innerHTML=`<div class="report-head"><h2>${esc(state.school.name)}</h2><p>${esc(state.school.location||"Liberia")}${state.school.phone?" · "+esc(state.school.phone):""}</p>${state.school.motto?`<p>${esc(state.school.motto)}</p>`:""}<h3>STUDENT REPORT CARD</h3><p>Academic year ${esc(year)}</p></div><div class="report-meta"><div><b>Student:</b> ${esc(s.name)}</div><div><b>Student ID:</b> ${esc(s.id)}</div><div><b>Class:</b> ${esc(s.className)}</div><div><b>Guardian:</b> ${esc(s.guardian||"—")}</div></div><div class="table-wrap"><table><thead><tr><th rowspan="2">Subject</th><th colspan="4">Semester 1</th><th colspan="4">Semester 2</th><th rowspan="2">Yearly avg.</th></tr><tr><th>First</th><th>Second</th><th>Third</th><th>Exam / Avg.</th><th>Fourth</th><th>Fifth</th><th>Sixth</th><th>Exam / Avg.</th></tr></thead><tbody>${subjects.map(r=>`<tr><td>${esc(r.subject)}</td><td>${r.m1.p1??"—"}</td><td>${r.m1.p2??"—"}</td><td>${r.m1.p3??"—"}</td><td>${r.m1.exam??"—"} / ${mark(r.avg1)}</td><td>${r.m2.p4??"—"}</td><td>${r.m2.p5??"—"}</td><td>${r.m2.p6??"—"}</td><td>${r.m2.exam??"—"} / ${mark(r.avg2)}</td><td>${mark(r.yearAvg)}</td></tr>`).join("")}</tbody></table></div><div class="report-summary"><span><b>Overall yearly average:</b> ${yearAvg===null?"Awaiting both semester averages":yearAvg.toFixed(1)+"/100"}</span><span><b>Standing:</b> ${yearAvg===null?"Incomplete":yearAvg>=Number(state.grading.passMark)?"Pass":"Needs improvement"}</span></div><p class="help-text">Semester average = (three period marks + exam) ÷ 4. Yearly average = (Semester 1 average + Semester 2 average) ÷ 2. Marks below 75 are highlighted red. Confirm the school's approved policy before official use.</p><div class="report-signatures"><span>Class teacher's signature</span><span>Principal's signature</span><span>Parent / guardian</span></div>`;$("reportDialog").showModal();};
