  function calcSemester(student,year,sem){const rec=state.grades[`${student.id}|${year}|${sem}`]||{};const values=Object.values(rec).map(m=>{const keys=sem==="Semester 1"?["p1","p2","p3","exam"]:["p4","p5","p6","exam"];const a=keys.map(k=>m?.[k]);return a.every(v=>v!==null&&v!==undefined&&v!=="")?a.reduce((x,y)=>x+Number(y),0)/4:null;}).filter(v=>v!==null);return values.length?values.reduce((x,y)=>x+y,0)/values.length:null;}
